template:
{{ define "studyclub.discord" -}}
{{- /* 멘션 없음. 팀 역할 멘션(<@&역할ID>)은 대상이 정해지면 붙인다. TBD */ -}}
{{- $env := "" -}}{{- if .Vars -}}{{- $env = .Vars.env -}}{{- end -}}
{{- $nf := len .Alerts.Firing -}}
{{- $nr := len .Alerts.Resolved -}}
{{- $head := "✅" -}}{{- if gt $nf 0 -}}{{- $head = "🔴" -}}{{- end -}}
{{- $what := "" -}}
{{- if gt $nf 0 -}}{{- $what = printf "발생 %d건" $nf -}}{{- end -}}
{{- if gt $nr 0 -}}
{{- if $what -}}{{- $what = printf "%s · 해소 %d건" $what $nr -}}
{{- else -}}{{- $what = printf "해소 %d건" $nr -}}{{- end -}}
{{- end -}}
{{- if gt $nf 8 -}}{{- $what = printf "%s · 앞 8건만" $what -}}{{- end -}}
{{- $done := "" -}}
{{- range $j, $a := .Alerts.Resolved -}}
{{- $nm2 := reReplaceAll "^.studyclub. " "" (index $a.Labels "alertname") -}}
{{- if $a.Labels.uri -}}{{- $nm2 = printf "%s(%s)" $nm2 $a.Labels.uri -}}{{- end -}}
{{- if $j -}}{{- $done = printf "%s, %s" $done $nm2 -}}{{- else -}}{{- $done = $nm2 -}}{{- end -}}
{{- end -}}
{{- $body := printf "%s %s · %s" $head $env $what -}}
{{- if $done -}}{{- $body = printf "%s\n✅ %s" $body $done -}}{{- end -}}
{
  "allowed_mentions": { "parse": [] },
  "content": {{ data.ToJSON $body }},
  "embeds": [
{{- range $i, $a := .Alerts.Firing }}
{{- if lt $i 8 }}
{{- $sev := index $a.Labels "severity" -}}
{{- $icon := "🔴" -}}{{- $color := 15158332 -}}
{{- if eq $sev "warning" -}}{{- $icon = "🟠" -}}{{- $color = 15105570 -}}{{- end -}}
{{- $name := reReplaceAll "^.studyclub. " "" (index $a.Labels "alertname") -}}
{{- $where := "" -}}{{- if $a.Labels.uri -}}{{- $where = printf " · %s" $a.Labels.uri -}}{{- end -}}
{{- $kv := "" -}}
{{- if $a.Values -}}
{{- $u := or $a.Annotations.unit "" -}}
{{- $v := "" -}}
{{- if or (eq $u "건") (eq $u "대") -}}{{- $v = printf "%.0f" (index $a.Values "A") -}}
{{- else -}}{{- $v = printf "%.4g" (index $a.Values "A") -}}{{- end -}}
{{- if $u -}}{{- $v = printf "%s %s" $v $u -}}{{- end -}}
{{- $kv = printf "\n%s : %s" (or $a.Annotations.metric "값") $v -}}
{{- end -}}
{{- $foot := printf "studyclub · %s" $env -}}
{{- if $sev -}}{{- $foot = printf "%s · %s" $foot $sev -}}{{- end -}}
  {{ if $i }},{{ end }}{
      "title": {{ data.ToJSON (printf "%s %s%s" $icon $name $where) }},
      "color": {{ $color }},
      "description": {{ data.ToJSON (printf "**%s**\n%s%s" (or $a.Annotations.summary "") (or $a.Annotations.description "") $kv) }},
      "footer": { "text": {{ data.ToJSON $foot }} },
      "timestamp": {{ data.ToJSON ($a.StartsAt.Format "2006-01-02T15:04:05Z07:00") }}
    }
{{- end }}
{{- end }}
  ]
}
{{- end }}
